ALTER TABLE futures_contracts ADD COLUMN IF NOT EXISTS identity_state TEXT NOT NULL DEFAULT 'PARTIAL';
ALTER TABLE futures_contracts ADD COLUMN IF NOT EXISTS identity_reason TEXT NOT NULL DEFAULT 'EXPIRATION_SOURCE_PENDING';
ALTER TABLE futures_contracts ADD COLUMN IF NOT EXISTS expiration_source_url TEXT;
ALTER TABLE futures_observations ADD COLUMN IF NOT EXISTS contract_identity_state TEXT NOT NULL DEFAULT 'CONTRACT_IDENTITY_PENDING';
ALTER TABLE futures_observations ADD COLUMN IF NOT EXISTS parser_version TEXT NOT NULL DEFAULT 'commodity-futures-v3';
ALTER TABLE futures_observations ADD COLUMN IF NOT EXISTS raw_checksum TEXT;
ALTER TABLE futures_product_roots ADD COLUMN IF NOT EXISTS product_state TEXT NOT NULL DEFAULT 'IDENTITY_PARTIAL';
ALTER TABLE futures_product_roots ADD COLUMN IF NOT EXISTS missing_reason TEXT NOT NULL DEFAULT 'OFFICIAL_PRODUCT_METADATA_PENDING';
ALTER TABLE commodity_futures_coverage ADD COLUMN IF NOT EXISTS source_state TEXT NOT NULL DEFAULT 'SOURCE_PENDING';
ALTER TABLE commodity_futures_coverage ADD COLUMN IF NOT EXISTS contract_state TEXT NOT NULL DEFAULT 'PARTIAL';
ALTER TABLE commodity_futures_coverage ADD COLUMN IF NOT EXISTS front_contract_state TEXT NOT NULL DEFAULT 'PENDING';
ALTER TABLE commodity_futures_coverage ADD COLUMN IF NOT EXISTS detail_state TEXT NOT NULL DEFAULT 'NOT_READY';
ALTER TABLE futures_front_contracts ADD COLUMN IF NOT EXISTS selection_date DATE;
ALTER TABLE futures_front_contracts ADD COLUMN IF NOT EXISTS selection_reason TEXT;
ALTER TABLE futures_front_contracts ADD COLUMN IF NOT EXISTS calculation_version TEXT;
ALTER TABLE futures_front_contracts ADD COLUMN IF NOT EXISTS verification_status TEXT NOT NULL DEFAULT 'PENDING';
UPDATE futures_product_roots SET product_state=CASE WHEN license_status='LICENSE_PENDING' THEN 'LICENSE_CONSTRAINED' WHEN license_status='PUBLIC_DELAYED' THEN 'PUBLIC_DELAYED' WHEN verification_status='VERIFIED' THEN 'NOT_READY' ELSE 'SOURCE_CONSTRAINED' END,missing_reason=CASE WHEN license_status='LICENSE_PENDING' THEN 'OFFICIAL_DATA_LICENSE_REQUIRED' WHEN license_status='PUBLIC_DELAYED' THEN 'DELAYED_SOURCE_CONTRACT_NOT_VERIFIED' WHEN verification_status='VERIFIED' THEN 'LISTED_CONTRACT_IDENTITY_PENDING' ELSE 'OFFICIAL_PRODUCT_METADATA_PENDING' END WHERE asset_class='COMMODITY_FUTURES';
UPDATE futures_contracts SET identity_state='PARTIAL',identity_reason=CASE WHEN root_id IS NULL THEN 'ROOT_LINK_CONFLICT_AND_EXPIRATION_SOURCE_PENDING' WHEN expiration IS NULL THEN 'EXPIRATION_SOURCE_PENDING' ELSE 'SOURCE_SEMANTICS_PENDING' END,verification_status='PARTIAL' WHERE asset_class='COMMODITY_FUTURES';
UPDATE futures_observations SET contract_identity_state='CONTRACT_IDENTITY_PENDING',quality_status='CONTRACT_IDENTITY_PENDING' WHERE asset_class='COMMODITY_FUTURES';
UPDATE futures_contracts SET expiration='2026-08-31',identity_state='VERIFIED',identity_reason='EXPIRATION_VERIFIED_ROOT_LINK_VERIFIED',verification_status='VERIFIED',expiration_source_url='https://www.cmegroup.com/daily_bulletin/current/Section15_Live_Cattle_Call_Options.pdf',status='ACTIVE' WHERE asset_class='COMMODITY_FUTURES' AND exchange='CME_GROUP' AND contract_symbol='LEQ26' AND root_id IS NOT NULL;
UPDATE futures_contracts SET expiration='2026-10-30',identity_state='VERIFIED',identity_reason='EXPIRATION_VERIFIED_ROOT_LINK_VERIFIED',verification_status='VERIFIED',expiration_source_url='https://www.cmegroup.com/daily_bulletin/current/Section15_Live_Cattle_Call_Options.pdf',status='ACTIVE' WHERE asset_class='COMMODITY_FUTURES' AND exchange='CME_GROUP' AND contract_symbol='LEV26' AND root_id IS NOT NULL;
UPDATE futures_observations o SET contract_identity_state='VERIFIED',quality_status='OFFICIAL_EXCHANGE_VERIFIED_CONTRACT' FROM futures_contracts c WHERE c.id=o.contract_id AND c.identity_state='VERIFIED' AND o.asset_class='COMMODITY_FUTURES';
UPDATE futures_product_roots SET product_state='PRODUCTION_READY',missing_reason='NONE' WHERE asset_class='COMMODITY_FUTURES' AND root_symbol='LE' AND exchange='CME_GROUP';
UPDATE commodity_futures_coverage c SET source_state=CASE WHEN r.license_status='LICENSE_PENDING' THEN 'LICENSE_CONSTRAINED' WHEN r.license_status='PUBLIC_DELAYED' THEN 'PUBLIC_DELAYED' WHEN r.product_state='PRODUCTION_READY' THEN 'PUBLIC_OFFICIAL_READY' ELSE 'SOURCE_CONSTRAINED' END,contract_state=CASE WHEN r.product_state='PRODUCTION_READY' THEN 'VERIFIED' ELSE 'PARTIAL' END,front_contract_state=CASE WHEN r.product_state='PRODUCTION_READY' THEN 'VERIFIED' ELSE 'PENDING' END,detail_state=CASE WHEN r.product_state='PRODUCTION_READY' THEN 'READY' WHEN r.license_status='LICENSE_PENDING' THEN 'LICENSE_CONSTRAINED_READY' WHEN r.license_status='PUBLIC_DELAYED' OR r.product_state='SOURCE_CONSTRAINED' THEN 'SOURCE_CONSTRAINED_READY' ELSE 'IDENTITY_PARTIAL' END,freshness_status=CASE WHEN r.product_state='PRODUCTION_READY' THEN 'MARKET_CLOSED' WHEN r.license_status='LICENSE_PENDING' THEN 'LICENSE_PENDING' WHEN r.license_status='PUBLIC_DELAYED' THEN 'SOURCE_DELAYED' ELSE 'SOURCE_PENDING' END,lifecycle_status=CASE WHEN r.product_state='PRODUCTION_READY' THEN 'MINIMUM_READY' ELSE 'PENDING' END,continuous_status='PREREQUISITES_PENDING',roll_audit_status='PREREQUISITES_PENDING',coverage_status=CASE WHEN r.product_state='PRODUCTION_READY' THEN 'FIRST_PATH_READY' WHEN r.license_status='LICENSE_PENDING' THEN 'LICENSE_CONSTRAINED' WHEN r.license_status='PUBLIC_DELAYED' THEN 'PUBLIC_DELAYED' ELSE 'SOURCE_CONSTRAINED' END,updated_at=NOW() FROM futures_product_roots r WHERE r.id=c.root_id AND r.asset_class='COMMODITY_FUTURES';
UPDATE futures_front_contracts f SET selection_rule='NEAREST_NON_EXPIRED_VERIFIED_CONTRACT',selection_date=CURRENT_DATE,selection_reason='NEAREST_VERIFIED_ACTIVE_CONTRACT',calculation_version='commodity-front-v1',verification_status='VERIFIED',active_contract_id=(SELECT c.id FROM futures_contracts c WHERE c.root_id=f.root_id AND c.identity_state='VERIFIED' AND c.expiration>=CURRENT_DATE ORDER BY c.expiration LIMIT 1),updated_at=NOW() WHERE f.root_id=(SELECT id FROM futures_product_roots WHERE asset_class='COMMODITY_FUTURES' AND root_symbol='LE' AND exchange='CME_GROUP') AND EXISTS(SELECT 1 FROM futures_contracts c WHERE c.root_id=f.root_id AND c.identity_state='VERIFIED' AND c.expiration>=CURRENT_DATE);
